"use client";

import { useState, useEffect, Suspense, useRef } from "react";
import { Box, User, Film, X, Heart, Search, ChevronLeft, ChevronRight, ArrowUpRight} from "lucide-react";
import { supabase } from "../lib/supabase";
import Link from "next/link";
import { useSearchParams } from "next/navigation";

interface Movie {
  id: string;
  title: string;
  url: string;
  creator: string;
  description: string;
  tool: string;
  type: string;
  thumbnailUrl?: string;
  tags: string[];
  category: string;
  likes: number;
  toolUrl?: string;
}

function HomeContent() {
  const searchParams = useSearchParams();
  const [selectedTag, setSelectedTag] = useState<string | null>(null); 
  const [selectedVideo, setSelectedVideo] = useState<Movie | null>(null);
  const [movieList, setMovieList] = useState<Movie[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'movie' | 'tutorial'>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTool, setSelectedTool] = useState('all');
  const [sortBy, setSortBy] = useState<'newest' | 'popular'>('newest');
  const [hasLiked, setHasLiked] = useState(false);
  const [likedMovieIds, setLikedMovieIds] = useState<string[]>([]);
  const tagScrollRef = useRef<HTMLDivElement>(null);

  const GAS_URL = "https://script.google.com/macros/s/AKfycbypovG7-jZfJlkzhtjkX68UIqcv5P6-W77fl7b3U_7tOorFujl23UEOItQVB5as1Zet8Q/exec";

  const handleTagScroll = (direction: 'left' | 'right') => {
    if (tagScrollRef.current) {
      const scrollAmount = 500; // 1回のクリックで動く距離（ピクセル数。お好みで調整してください）
      tagScrollRef.current.scrollBy({
        left: direction === 'left' ? -scrollAmount : scrollAmount,
        behavior: 'smooth' 
      });
    }
  };

  // 1. URLからタグを取得する処理
  useEffect(() => {
    const tagFromUrl = searchParams.get("tag");
    if (tagFromUrl) {
      setSelectedTag(tagFromUrl);
    }
  }, [searchParams]);
  

  // 2. データの初期化（GASから動画取得 ➔ Supabaseでいいね同期）を一気に行う
  useEffect(() => {
    const initApp = async () => {
      try {
        // --- STEP A: GASから最新の動画リストを取得 ---
        const response = await fetch(GAS_URL);
        const fetchedMovies: Movie[] = await response.json();

        // --- STEP B: Supabaseから「いいね」を取得 ---
        const { data: dbData } = await supabase.from('movies').select('*');
        
        let finalMovies = fetchedMovies;

        if (dbData) {
          // DBにいない動画を特定（fetchedMoviesを基準にする）
          const missingMovies = fetchedMovies.filter(m => 
            !dbData.find(d => String(d.id) === String(m.id))
          );

          if (missingMovies.length > 0) {
            // DBにいない動画を追加
            const newRows = missingMovies.map(m => ({ id: m.id, likes: 0 }));
            await supabase.from('movies').insert(newRows);
            
            // 最新のDB情報を再取得
            const { data: updatedDbData } = await supabase.from('movies').select('*');
            if (updatedDbData) {
              finalMovies = mergeLikes(fetchedMovies, updatedDbData);
            }
          } else {
            // 全員揃っていればそのまま合体
            finalMovies = mergeLikes(fetchedMovies, dbData);
          }
        }
        
        setMovieList(finalMovies);
      } catch (error) {
        console.error("初期化に失敗しました:", error);
      } finally {
        setLoading(false);
      }
    }; 

    // ヘルパー関数：動画リストにDBのいいね数を合成する
    const mergeLikes = (baseMovies: Movie[], dbData: any[]) => {
      return baseMovies.map(m => {
        const dbItem = dbData.find(d => String(d.id) === String(m.id));
        return dbItem ? { ...m, likes: dbItem.likes } : { ...m, likes: 0 };
      });
    };

    initApp();
  }, []); // ページ読み込み時に1回だけ実行
  
  // ページ読み込み時に、いいね済みの動画IDをローカルストレージから全て抜き出す
useEffect(() => {
  if (movieList.length === 0) return;
  
  const savedIds: string[] = [];
  movieList.forEach(m => {
    if (localStorage.getItem(`liked_movie_${m.id}`) === "true") {
      savedIds.push(String(m.id));
    }
  });
  setLikedMovieIds(savedIds);
}, [movieList]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-[#020617] text-white">
        <div className="text-xl font-bold animate-pulse">動画データを読み込み中...</div>
      </div>
    );
  }

const aiTools = [
  { name: 'Luma Dream Machine', url: 'https://lumalabs.ai/', desc: '超リアルな動画生成' },
  { name: 'Runway Gen-3', url: 'https://runwayml.com/', desc: 'プロ御用達の多機能AI' },
  { name: 'Kling AI', url: 'https://klingai.com/', desc: '驚異の10秒動画生成' },
  { name: 'Pika Art', url: 'https://pika.art/', desc: 'アニメ・可愛い表現に強い' },
];

  // YouTube IDを取得する最強の関数
  const getYouTubeId = (url: string) => {
    const regExp = /^.*(youtu\.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;      
  };
  
  const handleLike = async (id: string) => {
    // 1. ブラウザの記憶（LocalStorage）をチェックし、すでにいいね済みの場合は何もしない
    const localId = `liked_movie_${id}`;
    if (localStorage.getItem(localId) === "true") return;     
    // 2. 画面上の数値を即座に +1（型違いエラー防止のため String に変換して比較）
    setMovieList(prev => 
      prev.map(m => String(m.id) === String(id) ? { ...m, likes: m.likes + 1 } : m)
    );  
    // 3. ブラウザに「この動画はいいねした」という記憶を保存
    localStorage.setItem(localId, "true");
    setLikedMovieIds(prev => [...prev, String(id)]);  
    // 4. Supabaseの数値を+1（視聴ページと完全に合わせるため、Number で数値化して送る！）
    const { error } = await supabase.rpc('increment_likes', { row_id: Number(id) });  
    if (error) {
      console.error("保存に失敗しました:", error);
    }
  };

const tagCounts = movieList.reduce((acc, item) => {
  item.tags?.forEach(tag => {
    // すでにそのタグが箱にあれば +1、なければ 1 にする
    acc[tag] = (acc[tag] || 0) + 1;
  });
  return acc;
}, {} as Record<string, number>);

const filteredMovies = movieList.filter(movie => {
      // ① カテゴリ
      const matchesCategory = filter === 'all' || movie.category === filter;
    // ② 検索
    const matchesSearch = 
    movie.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    movie.creator.toLowerCase().includes(searchTerm.toLowerCase());
    // ★ タグ
    const isNoTagSelected = !selectedTag || selectedTag === "all" || selectedTag === "すべて"; 
    movie.tags?.includes(selectedTag);
    // ③ ツール
    const matchesTag = isNoTagSelected || movie.tags?.includes(selectedTag as string);
    const matchesTool = 
    !selectedTool ||              // ツールが未選択(null)ならOK
    selectedTool === "all" ||     // "all" ならOK
    selectedTool === "すべて" ||   // "すべて" ならOK
    movie.tool === selectedTool;  // それ以外は、実際のツール名と一致するかチェック
  
    return matchesCategory && matchesSearch && matchesTool && matchesTag;    
  });
  const sortedMovies = [...filteredMovies].sort((a, b) => {
    if (sortBy === "newest") {
     return parseInt(b.id) - parseInt(a.id);
    }
     return b.likes - a.likes;
  });

  return (
    <div className="min-h-screen bg-[#020617] text-white p-8">         
    
      {/* --- ヘッダー（ロゴ） --- */}
      <header className="sticky top-0 z-50 w-full border-b border-white/10 bg-black/60 backdrop-blur-md">
        <div className="container mx-auto flex h-16 items-center justify-between px-4">
          <div className="flex flex-col items-start group cursor-pointer">
            <div className="flex items-center gap-2">
              <Box className="h-6 w-6 text-blue-500" />
              <span className="text-xl font-bold tracking-tighter text-white">
                AI CINEMA HUB
              </span>
            </div>
            <div className="h-0.5 w-full bg-blue-500 scale-x-0 group-hover:scale-x-100 transition-transform duration-300 origin-left" />
          </div>
          <Link href="/submit">
          <button className="rounded-full bg-blue-600 px-4 py-1.5 text-sm font-medium hover:bg-blue-500 transition-colors active:scale-95">
          動画を投稿・推薦する
          </button>
          </Link>
        </div>
      </header>      

      {/* --- メインコンテンツ --- */}
      <div className="container mx-auto px-4 py-8">
        <div className="mb-8">
          <h1 className="text-2xl font-bold md:text-3xl">最新のAI動画作品</h1>
          <p className="text-sm text-gray-400 mt-2">
            次世代のクリエイターによるAI映像のハブへようこそ
          </p>
        </div>

{/* --- 検索窓 --- */}
<div className="relative mb-8 mx-auto max-w-md">
  <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
    <Search className="h-4 w-4 text-gray-400" />
  </div>
  <input
    type="text"
    placeholder="作品名やクリエイター名で検索..."
    value={searchTerm}
    onChange={(e) => setSearchTerm(e.target.value)} // 文字が入るたびに状態を更新
    className="w-full rounded-full bg-white/5 border border-white/10 py-2 pl-10 pr-4 text-sm text-white placeholder-gray-500 focus:border-blue-500/50 focus:bg-white/10 focus:outline-none focus:ring-1 focus:ring-blue-500/50 transition-all"
  />
</div>
{/* --- 並び替えスイッチ --- */}
<div className="mb-6 flex justify-end px-4 max-w-6xl mx-auto">
  <div className="flex bg-white/5 rounded-lg p-1 p-1 border border-white/10">
    <button
      onClick={() => setSortBy('newest')}
      className={`px-4 py-1.5 text-xs font-medium rounded-md transition-all ${
        sortBy === 'newest' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'
      }`}
    >
      新着順
    </button>
    <button
      onClick={() => setSortBy('popular')}
      className={`px-4 py-1.5 text-xs font-medium rounded-md transition-all ${
        sortBy === 'popular' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'
      }`}
    >
      人気順
    </button>
  </div>
</div>

{/* --- カテゴリフィルター --- */}
<div className="mb-8 flex justify-center gap-4">
  {(['all', 'movie', 'tutorial'] as const).map((cat) => (
    <button
      key={cat}
      onClick={() => setFilter(cat)}
      className={`rounded-full px-6 py-2 text-sm font-medium transition-all ${
        filter === cat
          ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30'
          : 'bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white'
      }`}
    >
      {cat === 'all' ? 'すべて' : cat === 'movie' ? '作品' : '解説動画'}
    </button>
  ))}
</div>
{/* --- ツールタグ --- */}
<div className="mb-8 flex flex-wrap justify-center gap-2">
  
{/* フィルターリセットボタン */}
{(searchTerm || filter !== 'all' || selectedTool !== 'all') && (
  <button 
    onClick={() => {
      setSearchTerm('');
      setFilter('all');
      setSelectedTool('all');
    }}
    className="text-xs text-gray-500 hover:text-white underline underline-offset-4"
  >
    フィルターをリセット
  </button>
)}  
  {/* 「すべて」ボタン */}
  <button 
  onClick={() => setSelectedTool("all")} 
  className={selectedTool === "all" ? "active-style" : "normal-style"}
>
  All Tools
</button>
  
  {/* データにあるツールを自動でボタンにする */}
  {Array.from(new Set(movieList.map(m => m.tool))).map((toolName) => (
    <button
      key={toolName}
      onClick={() => setSelectedTool(toolName)}
      className={`rounded-full px-4 py-1.5 text-xs font-medium transition-all ${
        selectedTool === toolName
          ? 'bg-blue-500 text-white shadow-lg shadow-blue-500/30'
          : 'bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white'
      }`}
    >
      #{toolName}
    </button>
  ))}
</div>

{/* flex-nowrap : 折り返さずに横一列に並べる
  overflow-x-auto : はみ出た分をスクロール可能にする
  pb-2 : スクロールバーがボタンに被らないように少し下に隙間を作る
  scrollbar-hide : (オプション) スクロールバーを隠してスッキリさせる
*/}
<div className="relative w-full mb-8 group/tags px-4">
{/* 左矢印ボタン */}
<button
    onClick={() => handleTagScroll('left')}
    className="absolute left-6 top-1/2 -translate-y-1/2 z-10 p-2 rounded-full bg-slate-900/80 border border-white/10 text-gray-400 hover:text-white hover:bg-slate-800 transition-all duration-200 shadow-xl opacity-0 group-hover/tags:opacity-100 backdrop-blur-sm"
    aria-label="左にスクロール"
  >
    <ChevronLeft size={18} />
  </button>
{/* 横スクロール対応のタグエリア */}
<div 
    ref={tagScrollRef} 
    className="flex gap-2 overflow-x-auto whitespace-nowrap pb-3 pt-1 scrollbar-none md:justify-start max-w-full px-6"
  >
  {/* 「すべて」ボタン */}
  <button 
      onClick={() => setSelectedTag(null)}
      className={`flex-shrink-0 px-4 py-2 rounded-full text-sm transition-all ${
        !selectedTag || selectedTag === "すべて" 
          ? "bg-blue-600 text-white font-bold" 
          : "bg-white/5 text-gray-400 hover:text-white"
      }`}
    >
      #すべて
    </button>
  
  {/* 各タグボタン */}
  {Array.from(new Set(movieList.flatMap(m => m.tags || []))).map(tag => (
      <button
        key={tag}
        onClick={() => setSelectedTag(tag)}
        className={`flex-shrink-0 px-3 py-2 rounded-full text-xs transition-all ${
          selectedTag === tag 
            ? 'bg-blue-600 text-white font-bold' 
            : 'bg-white/5 text-gray-400 hover:text-white'
          }`}
      >
        #{tag} ({tagCounts[tag] || 0})
      </button>
    ))}
  </div>
{/* 右矢印ボタン */}
<button
    onClick={() => handleTagScroll('right')}
    className="absolute right-6 top-1/2 -translate-y-1/2 z-10 p-2 rounded-full bg-slate-900/80 border border-white/10 text-gray-400 hover:text-white hover:bg-slate-800 transition-all duration-200 shadow-xl opacity-0 group-hover/tags:opacity-100 backdrop-blur-sm"
    aria-label="右にスクロール"
  >
    <ChevronRight size={18} />
  </button>
</div>


        {/* --- 動画グリッド --- */}
        {/* grid-cols-1 : 基本（スマホ）は1列
  sm:grid-cols-2 : 640px以上（タブレット）になったら2列
  lg:grid-cols-3 : 1024px以上（PC）になったら3列
  gap-4 : スマホでは隙間を少し狭く(16px)
  sm:gap-6 : 画面が広くなったら隙間も広く(24px)
*/}

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-6">
        {sortedMovies.map((movie) => {
    const videoId = getYouTubeId(movie.url);
    const thumbnailUrl = movie.thumbnailUrl || (videoId 
      ? `https://img.youtube.com/vi/${videoId}/mqdefault.jpg` 
      : "https://via.placeholder.com/480x270/0f172a/ffffff?text=No+Thumbnail");

      return (
        <Link
          href={`/movie/${movie.id}`}
          key={movie.id}
          className="group relative flex flex-col overflow-hidden rounded-xl border border-white/5 bg-[#0f172a] text-left transition-all duration-300 hover:scale-[1.03] hover:border-blue-500/50 hover:shadow-2xl hover:shadow-blue-500/10"
        >
          {/* --- カテゴリバッジ --- */}
          <div className="absolute top-2 left-2 z-10 flex gap-2">
            <span className={`rounded px-2 py-0.5 text-[10px] font-bold text-white shadow-lg ${
              movie.category === 'tutorial' ? 'bg-green-600' : 'bg-blue-600'
            }`}>
              {movie.category === 'tutorial' ? 'TUTORIAL' : 'MOVIE'}
            </span>
          </div>
      
          {/* 動画サムネイル部分（buttonからdivに変更） */}
          <div className="relative aspect-video w-full overflow-hidden">
            <img
              src={thumbnailUrl}
              alt={movie.title}
              className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-110"
            />
            <div className="absolute inset-0 bg-black/20 group-hover:bg-black/0 transition-colors" />
            <div className="absolute bottom-2 right-2 rounded bg-black/60 px-2 py-0.5 text-[10px] backdrop-blur-sm text-white">
              {movie.type === 'youtube' ? 'YOUTUBE' : 'TIKTOK'}
            </div>
          </div>
      
          {/* 情報エリア */}
          <div className="p-4">
            <h3 className="line-clamp-2 text-sm font-semibold leading-snug text-white group-hover:text-blue-400 transition-colors">
              {movie.title}
            </h3>
            <div className="mt-3 flex items-center justify-between">
              <div className="flex items-center gap-1.5 text-xs text-gray-400">
                <User className="h-3.5 w-3.5" />
                <span className="truncate max-w-[80px]">{movie.creator}</span>
              </div>
      
              <div className="flex items-center gap-3">
                <div className="mt-2 flex flex-wrap gap-1">
                  {movie.tags?.map(tag => (
                    <span
                      key={tag}
                      onClick={(e) => {
                        e.preventDefault(); // ページ移動を防ぐ
                        e.stopPropagation(); // 親（Link）にクリックを伝えない
                        setSelectedTag(tag);
                        window.scrollTo({ top: 0, behavior: 'smooth' });
                      }}
                      className="cursor-pointer text-[10px] text-gray-500 hover:text-blue-400"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>

                {/* いいねボタン */}
                {(() => {
                // ★ ループ内で、この動画が「いいね済みリスト」に入っているか調べる
                const hasLiked = likedMovieIds.includes(String(movie.id));
                return (
                <button
                 disabled={hasLiked} // ★すでにいいね済みの場合はボタンを押せなくする
                 onClick={(e) => {
                   e.preventDefault(); // ページ移動を防ぐ
                   e.stopPropagation(); // 親（Link）にクリックを伝えない
                   if (hasLiked) return;

                   if (handleLike) {
                    handleLike(movie.id);
                  }
               
                   handleLike(movie.id);
                   setHasLiked(true); // ★押した瞬間にトップページ側の見た目も即座にロック
                 }}
                 className={`flex items-center gap-1 text-xs transition-colors group/like ${
                   hasLiked 
                     ? "text-pink-500 cursor-default" // ★いいね済みの時は最初からピンク色
                     : "text-gray-400 hover:text-pink-500" // 未いいねの時
                 }`}
               >
                 <Heart 
                   className={`h-3.5 w-3.5 ${
                     hasLiked 
                       ? "fill-pink-500 text-pink-500" // ★いいね済みの時はハートをピンクで塗りつぶす
                       : "group-hover/like:fill-pink-500"
                   }`} 
                 />
                 <span className={hasLiked ? "font-bold text-pink-500" : ""}>
                   {movie.likes}
                 </span>
                </button>
                );
              })()}
      
                <button
                  onClick={(e) => {
                    e.preventDefault(); // ページ移動を防ぐ
                    e.stopPropagation(); // 親（Link）にクリックを伝えない
                    setSelectedTool(movie.tool);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                  }}
                  className="rounded-full border border-blue-500/30 bg-blue-500/10 px-2 py-0.5 text-[10px] font-medium text-blue-400 hover:bg-blue-500/20 hover:border-blue-500/50 transition-all"
                >
                  #{movie.tool}
                </button>
              </div>
            </div>
          </div>
        </Link>
      );
  })}
</div>
      </div>
      {/* --- AIツール・リンク集セクション --- */}
<section className="mt-20 border-t border-white/10 pt-10 pb-20">
  <h2 className="text-xl font-bold mb-6 text-center text-blue-400">Creator's Resources</h2>
  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 px-4 max-w-6xl mx-auto">
    {aiTools.map((tool) => (
      <a
        key={tool.name}
        // ⭕ 2日後にKling AIのアフィリンクが来たらここを差し替えます
        href={
          tool.name === 'Kling AI' ? 'https://klingai.com/' : 
          tool.name === 'Runway Gen-3' ? 'https://runwayml.com/' : 
          tool.url
        }
        target="_blank"
        rel="noopener noreferrer"
        className="group p-4 rounded-xl bg-white/5 border border-white/10 hover:border-blue-500/50 transition-all duration-300 hover:bg-blue-500/5 flex items-center justify-between gap-3"
      >
        {/* 左側：ロゴとテキストのセット（max-w で右端を確保します） */}
        <div className="flex items-center gap-3 max-w-[80%]">
          {/* --- ロゴ表示部分 --- */}
          <div className="flex-shrink-0 w-8 h-8 bg-white/10 rounded-lg flex items-center justify-center overflow-hidden">
            <img
              src={`https://www.google.com/s2/favicons?domain=${new URL(tool.url).hostname}&sz=64`}
              alt={`${tool.name} logo`}
              className="w-5 h-5 object-contain"
            />
          </div>
           
          {/* テキストエリア（truncate で省略表示にします） */}
          <div className="min-w-0">
            <h3 className="text-sm font-bold text-gray-200 group-hover:text-blue-400 transition-colors">
              {tool.name}
            </h3>
            {/* ★「truncate」を追加し、長すぎたら自動で「...」にします */}
            <p className="text-[10px] text-gray-500 mt-0.5 truncate">{tool.desc}</p>
          </div>
        </div>

        {/* 右側の矢印アイコン */}
        <ArrowUpRight 
          className="text-gray-600 group-hover:text-white transition-all duration-300 w-5 h-5 opacity-0 group-hover:opacity-100 flex-shrink-0 group-hover:translate-x-0.5 group-hover:-translate-y-0.5" 
          strokeWidth={2.5} 
        />
      </a>
    ))}
  </div>

  <footer className="w-full py-16 border-t border-slate-900 mt-20 text-center text-gray-500 text-sm">
    <div className="flex justify-center gap-6 mb-4">
      <Link href="/about"
        className="text-gray-400 hover:text-blue-400 transition-colors font-medium border-b border-transparent hover:border-blue-400 pb-1"
      >
        About
      </Link>
    </div>
    <p className="text-gray-600 text-xs tracking-widest uppercase">
      © 2026 AI CINEMA HUB
    </p>
  </footer>
</section>
      {/* --- ポップアップ（モーダル） --- */}
      {selectedVideo && (
  <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 p-4 backdrop-blur-sm">
    <div className="relative w-full max-w-4xl overflow-hidden rounded-2xl bg-[#0f172a] shadow-2xl">
      {/* 閉じるボタン */}
      <button
        onClick={() => setSelectedVideo(null)}
        className="absolute right-4 top-4 z-50 rounded-full bg-black/50 p-2 text-white hover:bg-white/20 transition-colors"
      >
        <X className="h-6 w-6" />
      </button>

      {/* 動画プレイヤー：YouTubeかTikTokかで中身を切り替え */}
      <div className={`w-full bg-black flex items-center justify-center ${
        selectedVideo.type === 'tiktok' ? 'aspect-[9/16] max-h-[70vh]' : 'aspect-video'
      }`}>
        {selectedVideo.type === 'youtube' ? (
          <iframe
            src={`https://www.youtube.com/embed/${getYouTubeId(selectedVideo.url)}?autoplay=1`}
            className="h-full w-full"
            allow="autoplay; encrypted-media"
            allowFullScreen
          />
        ) : (
          <iframe
            src={`https://www.tiktok.com/embed/v2/${selectedVideo.url.split('/video/')[1]}`}
            className="h-full w-full"
            allow="fullscreen"
          />
        )}
      </div>

      {/* 情報とボタン */}
<div className="p-6">
  <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
    <div>
      <h2 className="text-xl font-bold">{selectedVideo.title}</h2>
      <div className="mt-2 flex items-center gap-3 text-sm text-gray-400">
        <span className="flex items-center gap-1">
          <User className="h-4 w-4" /> {selectedVideo.creator}
        </span>
                
        <a
          href={selectedVideo.toolUrl || (
            selectedVideo.tool === 'Kling AI' ? 'https://klingai.com/' :
            selectedVideo.tool === 'Runway' ? 'https://runwayml.com/' :
            selectedVideo.tool === 'Pika' ? 'https://pika.art/' :
            'https://lumalabs.ai/dream-machine'
          )}
          target="_blank"
          rel="noopener noreferrer"
          className="rounded-md bg-blue-500/10 px-2 py-0.5 text-xs text-blue-400 border border-blue-500/20 hover:bg-blue-500/20 hover:text-white transition-all duration-200 cursor-pointer flex items-center gap-1"
          title={`${selectedVideo.tool}の公式サイトを開く`}
        >
          {selectedVideo.tool} <span className="text-[10px] opacity-60">↗</span>
        </a>
      </div>
    </div>
          
          {/* ボタンの文字と色を動的に変更 */}
          <a 
            href={selectedVideo.url} 
            target="_blank" 
            rel="noopener noreferrer"
            className={`flex items-center justify-center gap-2 rounded-full px-6 py-2.5 text-sm font-bold text-white transition-all hover:scale-105 active:scale-95 shadow-lg ${
              selectedVideo.type === 'youtube' 
                ? 'bg-red-600 hover:bg-red-700 shadow-red-600/20' 
                : 'bg-zinc-800 hover:bg-black shadow-zinc-900/40'
            }`}
          >
            <Film className="h-4 w-4" />
            {selectedVideo.type === 'youtube' ? 'YouTubeで視聴する' : 'TikTokで視聴する'}
          </a>
        </div>
      </div>
    </div>
  </div>
)}
    </div>
  );
}

export default function Home() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-[#020617]" />}>
      <HomeContent />
    </Suspense>
  );
}